m = N // 3
rem = N % 3

if rem == 0:
    prod = 1
    for k in range(1, m + 1):
        prod *= f(3 * k)
    answer = prod
elif rem == 1:
    prod = A
    for k in range(1, m + 1):
        prod *= f(3 * k + 1)
